"""The cost model fit and its cross-validated margin on synthetic runs."""
import argparse
import json

import pytest

from bench import calibrate
from bench.suite import TRANSFER_FIT_GROUPS, TRANSFER_HELDOUT_GROUP
from ragged.selection import MODEL_PATH, CostModel, features

# Times generated by known coefficients of the six terms.
TRUTH = {"classified": (30.0, 0.2, 0.0, 0.3, 0.02, 1.5), "naive": (15.0, 0.25, 10.0, 0.8, 0.0, 2.0)}
SHAPES = [(1, 4096, 2**20), (1, 65536, 2**20), (32, 8192, 2**19), (128, 4096, 2**18), (256, 2048, 2**17)]


def synthetic():
    inputs = []
    for d, b, n in SHAPES:
        for factor in (1, 16, 256):
            for op in ("sum", "softmax"):
                case = {"op": op, "elements": n, "segments": b, "D": d, "max_length": factor * n // b, "dtype": "f32"}
                x = features(*calibrate.shape(case), op=op)
                times = {s: sum(c * v for c, v in zip(TRUTH[s], x)) for s in TRUTH}
                entry = {"case": case, "selected": [], "l2_mib": 72.0,
                         "methods": {calibrate.METHOD[s]: [times[s]] for s in TRUTH}}
                inputs.append((("main", f"{op}-{d}-{b}-{factor}", 711), entry))
    return inputs


def test_fit_recovers_the_generating_coefficients_and_needs_no_margin():
    inputs = synthetic()
    coefficients = calibrate.fit(inputs)
    for family in ("reduce", "softmax"):
        for schedule, truth in TRUTH.items():
            assert coefficients[family][schedule] == pytest.approx(truth, abs=1e-3)
    margin, scores, excess = calibrate.margin_by_shape(inputs, dict(inputs))
    assert margin == 0.0 and scores[0.0] == len(inputs) >= max(scores.values())
    assert excess[0.0]["warm"] == excess[0.0]["cold"] and max(excess[0.0]["warm"]) <= calibrate.NOISE_TIE
    model = CostModel.from_dict(calibrate.model_data(coefficients, margin, {}, 72.0))
    assert calibrate.within(model, inputs) == len(inputs)


def test_points_keep_training_seeds_that_measured_both_schedules():
    inputs = synthetic()
    (key, entry), *_ = inputs
    found = {key: entry, ("main", "other", 712): entry,
             ("main", "one-schedule", 711): {**entry, "methods": {"ragged-naive": [1.0]}}}
    assert calibrate.points(found, [711]) == [(key, entry)]


def write_runs(root, group, shapes, l2_mib, seed=711):
    """results.json files of both schedules, timed by TRUTH on a GPU with an L2 of l2_mib."""
    for d, b, n in shapes:
        for factor in (1, 16, 256):
            for op in ("sum", "softmax"):
                case = {"op": op, "elements": n, "segments": b, "D": d, "max_length": factor * n // b, "dtype": "f32"}
                x = features(*calibrate.shape(case), op=op, l2_mib=l2_mib)
                cells = [{"method": calibrate.METHOD[s], "status": "measured",
                          "complete_call_cuda_event_ms": {"median": sum(c * v for c, v in zip(truth, x)) / 1000},
                          "cold_l2": {"complete_call_cuda_event_ms": {
                              "median": sum(c * v for c, v in zip(truth, x)) / 1000}}}
                         for s, truth in TRUTH.items()]
                path = root / group / f"{op}-{d}-{b}-{factor}" / f"seed-{seed}" / "rep-0" / "results.json"
                path.parent.mkdir(parents=True)
                path.write_text(json.dumps({"case": case, "methods": cells,
                                            "cuda_driver": {"l2_cache_size_bytes": int(l2_mib * 2**20)}}))


def test_transfer_refits_on_the_fixed_groups_and_reports_three_models(tmp_path, capsys):
    assert (TRANSFER_FIT_GROUPS, TRANSFER_HELDOUT_GROUP) == (("compare", "heldout"), "heldout2")
    write_runs(tmp_path, "compare", SHAPES[:2], 6.0)
    write_runs(tmp_path, "heldout", SHAPES[2:4], 6.0)
    write_runs(tmp_path, "heldout2", SHAPES[4:], 6.0)
    output = tmp_path / "refit.json"
    calibrate.run_transfer(argparse.Namespace(runs=tmp_path, seeds=[711], model=MODEL_PATH, output=output))
    data = json.loads(output.read_text())
    assert data["l2_mib"] == 6.0 and data["calibration"]["groups"] == ["compare", "heldout"]
    report = capsys.readouterr().out
    assert "fitted with an L2 of 72 MiB" in report and "(L2 6 MiB)" in report
    for l2 in ("warm", "cold"):
        assert f"{l2} L2, heldout2 runs" in report
    # The refit recovers the generating times exactly; the shipped model is only reported.
    assert report.count("refitted: 6 of 6 within 3%") == 2
    assert report.count("    shipped: ") == 2 and report.count(" L2 swapped: ") == 2
